// Hand-calc verification test for every build (plan-v2-final.md, Sections 7 and 14).
// Run: npm test   (Node >= 18, no dependencies)
// Expected values come from tests/handcalc-expected.json, generated by the
// independent Python reference (tests/reference/handcalc_reference.py).
import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const EXPECTED = JSON.parse(readFileSync(join(ROOT, 'tests/handcalc-expected.json'), 'utf8'));
const REL_TOL = 0.005;          // +/-0.5 %
const ABS_TOL_CLOSURE = 1e-6;   // kg/h

const BUILDS = [
  { name: 'claude', dir: 'site' },
  { name: 'gemini', dir: 'site/gemini' },
];
// Optional extra build directory (used to self-test this harness): EXTRA_BUILD=/path/to/dir npm test
if (process.env.EXTRA_BUILD) BUILDS.push({ name: 'extra', dir: process.env.EXTRA_BUILD });

function get(obj, path) {
  return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), obj);
}

function near(actual, expected, key) {
  assert.equal(typeof actual, 'number', `${key}: expected a number, got ${actual}`);
  assert.ok(Number.isFinite(actual), `${key}: not finite (${actual})`);
  if (key.endsWith('closureError')) {
    assert.ok(Math.abs(actual) <= ABS_TOL_CLOSURE, `${key}: |${actual}| > ${ABS_TOL_CLOSURE}`);
    return;
  }
  const rel = expected === 0 ? Math.abs(actual) : Math.abs(actual - expected) / Math.abs(expected);
  assert.ok(rel <= REL_TOL, `${key}: got ${actual}, expected ${expected} (off by ${(rel * 100).toFixed(3)} %)`);
}

// --- data audit: every value object must cite a known source ---
test('data.js: every value has a known sourceId', async () => {
  const { DATA } = await import(pathToFileURL(join(ROOT, 'site/js/data.js')));
  const missing = [];
  (function walk(o, path) {
    if (o && typeof o === 'object' && !Array.isArray(o)) {
      if ('value' in o || 'sourceId' in o) {
        if (!o.sourceId || !(o.sourceId in DATA.sources)) missing.push(path);
        return;
      }
      for (const [k, v] of Object.entries(o)) if (k !== 'sources' && k !== 'meta') walk(v, `${path}.${k}`);
    }
  })(DATA, 'DATA');
  assert.deepEqual(missing, [], `values without a valid sourceId: ${missing.join(', ')}`);
});

for (const build of BUILDS) {
  const modelPath = resolve(ROOT, build.dir, 'js/model.js');
  describe(`${build.name} build (${build.dir}/js/model.js)`, { skip: !existsSync(modelPath) && 'model.js not built yet' }, () => {
    let M;
    const load = async () => (M ??= await import(pathToFileURL(modelPath)));

    test('exports the API contract', async () => {
      await load();
      for (const fn of ['psat', 'tsat', 'hfg', 'solubility', 'bpe', 'massBalance', 'mvr', 'multiEffect', 'economics', 'simulate']) {
        assert.equal(typeof M[fn], 'function', `missing export ${fn}()`);
      }
      assert.equal(typeof M.DEFAULT_INPUTS, 'object', 'missing export DEFAULT_INPUTS');
    });

    test('DEFAULT_INPUTS match the hand-calc inputs', async () => {
      await load();
      for (const [k, v] of Object.entries(EXPECTED.inputs)) {
        assert.ok(k in M.DEFAULT_INPUTS, `DEFAULT_INPUTS missing key "${k}"`);
        if (typeof v === 'number') near(M.DEFAULT_INPUTS[k], v, `DEFAULT_INPUTS.${k}`);
        else assert.equal(M.DEFAULT_INPUTS[k], v, `DEFAULT_INPUTS.${k}`);
      }
    });

    test('hand-calc case reproduces every expected value within 0.5 %', async () => {
      await load();
      const out = M.simulate({});
      const failures = [];
      for (const [key, exp] of Object.entries(EXPECTED.base)) {
        try { near(get(out, key), exp, key); } catch (e) { failures.push(e.message); }
      }
      for (const [key, exp] of Object.entries(EXPECTED.baseFlags)) {
        if (get(out, key) !== exp) failures.push(`${key}: got ${get(out, key)}, expected ${exp}`);
      }
      assert.deepEqual(failures, [], `\n  ${failures.join('\n  ')}`);
    });

    test('ideal BPE option (useOsmotic=false, activityFactor=1)', async () => {
      await load();
      const out = M.simulate({ useOsmotic: false, activityFactor: 1.0 });
      near(out.BPE, EXPECTED.idealBPE.BPE, 'BPE');
      near(get(out, 'mvr.kWh_per_t'), EXPECTED.idealBPE['mvr.kWh_per_t'], 'mvr.kWh_per_t');
    });

    test('infeasible purge: feasible=false, no negative or NaN flows', async () => {
      await load();
      const out = M.simulate(EXPECTED.infeasibleMass.inputs);
      assert.equal(out.mass.feasible, false);
      for (const k of ['C', 'V', 'P']) {
        const v = out.mass[k];
        assert.ok(v === null || (Number.isFinite(v) && v >= 0), `mass.${k} = ${v} (must be null or >= 0)`);
      }
    });

    test('too many effects: feasible=false and maxFeasibleN', async () => {
      await load();
      const out = M.simulate(EXPECTED.infeasibleEffects.inputs);
      for (const [k, v] of Object.entries(EXPECTED.infeasibleEffects.expect)) assert.equal(get(out, k), v, k);
    });

    test('limiting cases', async () => {
      await load();
      // no lift -> no work
      const flat = M.mvr({ V: 1000, Tb_C: 60, BPE: 0, dT_heater: 1e-9, etaIs: 0.75, etaMotor: 0.95, gamma: 1.33 });
      assert.ok(Math.abs(flat.r - 1) < 1e-6, `r=${flat.r}`);
      assert.ok(Math.abs(flat.Welec_kW) < 1e-3, `W=${flat.Welec_kW}`);
      // tsat inverts psat
      for (const T of [40, 55.5, 66, 100]) assert.ok(Math.abs(M.tsat(M.psat(T)) - T) < 1e-6, `tsat(psat(${T}))`);
      // more BPE -> more work (monotonic)
      let prev = -Infinity;
      for (const BPE of [0, 2, 4, 6, 8, 10]) {
        const w = M.mvr({ V: 1000, Tb_C: 60, BPE, dT_heater: 6, etaIs: 0.75, etaMotor: 0.95, gamma: 1.33 }).Welec_kW;
        assert.ok(w > prev, `W not increasing at BPE=${BPE}`);
        prev = w;
      }
    });

    test('mass closure for 100 random feasible inputs', async () => {
      await load();
      let seed = 42;
      const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
      let checked = 0;
      for (let k = 0; k < 400 && checked < 100; k++) {
        const inp = { F: 2000 + rnd() * 48000, xF: 0.02 + rnd() * 0.09, zF: rnd() * 0.005,
                      T_C: 40 + rnd() * 60, purgeRatio: 0.005 + rnd() * 0.195 };
        const out = M.simulate(inp);
        if (!out.mass.feasible) continue;
        checked++;
        assert.ok(Math.abs(out.mass.closureError) < 1e-6, `closure ${out.mass.closureError} for ${JSON.stringify(inp)}`);
      }
      assert.ok(checked >= 50, `only ${checked} feasible random cases`);
    });
  });
}
